1	import { useState } from "react";
2	import { toast } from "sonner";
3	import {
4	  isBefore,
5	  parseISO,
6	  addDays,
7	  format,
8	  isToday,
9	  isTomorrow,
10	} from "date-fns";
11	import {
12	  CheckSquare,
13	  Plus,
14	  Trash2,
15	  Loader2,
16	  Calendar,
17	  AlertTriangle,
18	  Clock,
19	  Flag,
20	  ChevronDown,
21	  ChevronRight,
22	  AlertCircle,
23	} from "lucide-react";
24	import SidebarLayout from "@/components/SidebarLayout";
25	import { Card, CardContent } from "@/components/ui/card";
26	import { Button } from "@/components/ui/button";
27	import { Input } from "@/components/ui/input";
28	import { Textarea } from "@/components/ui/textarea";
29	import { Badge } from "@/components/ui/badge";
30	import { Checkbox } from "@/components/ui/checkbox";
31	import { Skeleton } from "@/components/ui/skeleton";
32	import {
33	  Select,
34	  SelectContent,
35	  SelectItem,
36	  SelectTrigger,
37	  SelectValue,
38	} from "@/components/ui/select";
39	import {
40	  Dialog,
41	  DialogContent,
42	  DialogHeader,
43	  DialogTitle,
44	  DialogTrigger,
45	} from "@/components/ui/dialog";
46	import {
47	  AlertDialog,
48	  AlertDialogAction,
49	  AlertDialogCancel,
50	  AlertDialogContent,
51	  AlertDialogDescription,
52	  AlertDialogFooter,
53	  AlertDialogHeader,
54	  AlertDialogTitle,
55	  AlertDialogTrigger,
56	} from "@/components/ui/alert-dialog";
57	import { useTasks, type Task, type TaskPriority } from "@/hooks/useTasks";
58	import { useTeam } from "@/hooks/useTeam";
59	import { useAuth } from "@/hooks/useAuth";
60	
61	// ── helpers ──────────────────────────────────────────────────────────────────
62	
63	function formatDueDate(dateStr: string): string {
64	  const d = parseISO(dateStr);
65	  if (isToday(d)) return "Today";
66	  if (isTomorrow(d)) return "Tomorrow";
67	  return format(d, "MMM d");
68	}
69	
70	// ── priority badge ────────────────────────────────────────────────────────────
71	
72	const PRIORITY_CONFIG: Record<
73	  TaskPriority,
74	  { label: string; className: string }
75	> = {
76	  low: { label: "Low", className: "bg-muted text-muted-foreground" },
77	  medium: { label: "Medium", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
78	  high: { label: "High", className: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400" },
79	};
80	
81	function PriorityBadge({ priority }: { priority: TaskPriority }) {
82	  const { label, className } = PRIORITY_CONFIG[priority];
83	  return (
84	    <span
85	      className={`inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full ${className}`}
86	    >
87	      <Flag className="h-2.5 w-2.5" />
88	      {label}
89	    </span>
90	  );
91	}
92	
93	// ── due date badge ────────────────────────────────────────────────────────────
94	
95	function DueDateBadge({ dueDate, isDone }: { dueDate: string; isDone: boolean }) {
96	  const today = new Date();
97	  const d = parseISO(dueDate);
98	  const overdue = !isDone && isBefore(d, today);
99	  const soon = !isDone && !overdue && isBefore(d, addDays(today, 3));
100	
101	  const className = overdue
102	    ? "text-red-600 dark:text-red-400"
103	    : soon
104	    ? "text-amber-600 dark:text-amber-400"
105	    : "text-muted-foreground";
106	
107	  return (
108	    <span className={`inline-flex items-center gap-1 text-xs ${className}`}>
109	      <Calendar className="h-3 w-3" />
110	      {formatDueDate(dueDate)}
111	    </span>
112	  );
113	}
114	
115	// ── assignee avatar ───────────────────────────────────────────────────────────
116	
117	function AssigneeAvatar({
118	  userId,
119	  members,
120	}: {
121	  userId: string;
122	  members: { user_id: string; email?: string }[];
123	}) {
124	  const member = members.find((m) => m.user_id === userId);
125	  const label = member?.email
126	    ? member.email[0].toUpperCase()
127	    : userId.slice(0, 1).toUpperCase();
128	  const title = member?.email ?? userId;
129	
130	  return (
131	    <span
132	      title={title}
133	      className="inline-flex items-center justify-center h-5 w-5 rounded-full bg-primary/10 text-primary text-[10px] font-semibold shrink-0"
134	    >
135	      {label}
136	    </span>
137	  );
138	}
139	
140	// ── task row ──────────────────────────────────────────────────────────────────
141	
142	interface TaskRowProps {
143	  task: Task;
144	  members: { user_id: string; email?: string }[];
145	  currentUserId: string;
146	  isAdmin: boolean;
147	  onToggle: (task: Task) => void;
148	  onDelete: (id: string) => void;
149	  isDeleting: boolean;
150	}
151	
152	function TaskRow({
153	  task,
154	  members,
155	  currentUserId,
156	  isAdmin,
157	  onToggle,
158	  onDelete,
159	  isDeleting,
160	}: TaskRowProps) {
161	  const isDone = task.status === "done";
162	  const canDelete = task.created_by === currentUserId || isAdmin;
163	
164	  return (
165	    <div className="flex items-center gap-3 px-4 py-2.5 group hover:bg-muted/30 transition-colors rounded-lg">
166	      <Checkbox
167	        checked={isDone}
168	        onCheckedChange={() => onToggle(task)}
169	        className="shrink-0"
170	        aria-label={isDone ? "Mark as todo" : "Mark as done"}
171	      />
172	
173	      <div className="flex-1 min-w-0">
174	        <p
175	          className={`text-sm leading-snug truncate ${
176	            isDone ? "line-through text-muted-foreground" : "text-foreground"
177	          }`}
178	        >
179	          {task.title}
180	        </p>
181	        {task.description && (
182	          <p className="text-xs text-muted-foreground truncate mt-0.5">
183	            {task.description}
184	          </p>
185	        )}
186	      </div>
187	
188	      <div className="hidden sm:flex items-center gap-2 shrink-0">
189	        {task.assigned_to && (
190	          <AssigneeAvatar userId={task.assigned_to} members={members} />
191	        )}
192	        <PriorityBadge priority={task.priority} />
193	        {task.due_date && (
194	          <DueDateBadge dueDate={task.due_date} isDone={isDone} />
195	        )}
196	      </div>
197	
198	      {canDelete && (
199	        <AlertDialog>
200	          <AlertDialogTrigger asChild>
201	            <Button
202	              variant="ghost"
203	              size="icon"
204	              className="h-7 w-7 opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive shrink-0 transition-opacity"
205	              disabled={isDeleting}
206	              aria-label="Delete task"
207	            >
208	              {isDeleting ? (
209	                <Loader2 className="h-3.5 w-3.5 animate-spin" />
210	              ) : (
211	                <Trash2 className="h-3.5 w-3.5" />
212	              )}
213	            </Button>
214	          </AlertDialogTrigger>
215	          <AlertDialogContent>
216	            <AlertDialogHeader>
217	              <AlertDialogTitle>Delete task?</AlertDialogTitle>
218	              <AlertDialogDescription>
219	                "{task.title}" will be permanently deleted. This cannot be undone.
220	              </AlertDialogDescription>
221	            </AlertDialogHeader>
222	            <AlertDialogFooter>
223	              <AlertDialogCancel>Cancel</AlertDialogCancel>
224	              <AlertDialogAction
225	                onClick={() => onDelete(task.id)}
226	                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
227	              >
228	                Delete
229	              </AlertDialogAction>
230	            </AlertDialogFooter>
231	          </AlertDialogContent>
232	        </AlertDialog>
233	      )}
234	    </div>
235	  );
236	}
237	
238	// ── task section ──────────────────────────────────────────────────────────────
239	
240	interface SectionProps {
241	  title: string;
242	  tasks: Task[];
243	  icon?: React.ReactNode;
244	  variant?: "default" | "destructive" | "warning";
245	  collapsed?: boolean;
246	  members: { user_id: string; email?: string }[];
247	  currentUserId: string;
248	  isAdmin: boolean;
249	  onToggle: (task: Task) => void;
250	  onDelete: (id: string) => void;
251	  deletingId: string | null;
252	}
253	
254	function TaskSection({
255	  title,
256	  tasks,
257	  icon,
258	  variant = "default",
259	  collapsed: defaultCollapsed = false,
260	  members,
261	  currentUserId,
262	  isAdmin,
263	  onToggle,
264	  onDelete,
265	  deletingId,
266	}: SectionProps) {
267	  const [open, setOpen] = useState(!defaultCollapsed);
268	
269	  const titleColor =
270	    variant === "destructive"
271	      ? "text-red-600 dark:text-red-400"
272	      : variant === "warning"
273	      ? "text-amber-600 dark:text-amber-400"
274	      : "text-foreground";
275	
276	  return (
277	    <div>
278	      <button
279	        onClick={() => setOpen((v) => !v)}
280	        className="flex items-center gap-2 mb-1 w-full text-left py-1 rounded-md hover:bg-muted/40 transition-colors px-1"
281	      >
282	        {open ? (
283	          <ChevronDown className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
284	        ) : (
285	          <ChevronRight className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
286	        )}
287	        {icon}
288	        <span className={`text-xs font-semibold uppercase tracking-wider ${titleColor}`}>
289	          {title}
290	        </span>
291	        <Badge variant="secondary" className="text-[10px] h-4 px-1.5 ml-auto">
292	          {tasks.length}
293	        </Badge>
294	      </button>
295	
296	      {open && (
297	        <div className="space-y-0.5">
298	          {tasks.map((task) => (
299	            <TaskRow
300	              key={task.id}
301	              task={task}
302	              members={members}
303	              currentUserId={currentUserId}
304	              isAdmin={isAdmin}
305	              onToggle={onToggle}
306	              onDelete={onDelete}
307	              isDeleting={deletingId === task.id}
308	            />
309	          ))}
310	        </div>
311	      )}
312	    </div>
313	  );
314	}
315	
316	// ── skeleton ──────────────────────────────────────────────────────────────────
317	
318	function TasksSkeleton() {
319	  return (
320	    <div className="space-y-3">
321	      {[1, 2, 3, 4].map((i) => (
322	        <div key={i} className="flex items-center gap-3 px-4 py-2.5">
323	          <Skeleton className="h-4 w-4 rounded shrink-0" />
324	          <Skeleton className="h-4 flex-1" />
325	          <Skeleton className="h-4 w-24 hidden sm:block" />
326	        </div>
327	      ))}
328	    </div>
329	  );
330	}
331	
332	// ── new task dialog ───────────────────────────────────────────────────────────
333	
334	interface NewTaskDialogProps {
335	  members: { user_id: string; email?: string }[];
336	  isCreating: boolean;
337	  onSubmit: (values: {
338	    title: string;
339	    description?: string;
340	    assigned_to?: string;
341	    priority: TaskPriority;
342	    due_date?: string;
343	  }) => void;
344	}
345	
346	function NewTaskDialog({ members, isCreating, onSubmit }: NewTaskDialogProps) {
347	  const [open, setOpen] = useState(false);
348	  const [title, setTitle] = useState("");
349	  const [description, setDescription] = useState("");
350	  const [assignedTo, setAssignedTo] = useState<string>("__none__");
351	  const [priority, setPriority] = useState<TaskPriority>("medium");
352	  const [dueDate, setDueDate] = useState("");
353	
354	  function handleSubmit(e: React.FormEvent) {
355	    e.preventDefault();
356	    if (!title.trim()) return;
357	    onSubmit({
358	      title: title.trim(),
359	      description: description.trim() || undefined,
360	      assigned_to: assignedTo !== "__none__" ? assignedTo : undefined,
361	      priority,
362	      due_date: dueDate || undefined,
363	    });
364	    // reset
365	    setTitle("");
366	    setDescription("");
367	    setAssignedTo("__none__");
368	    setPriority("medium");
369	    setDueDate("");
370	    setOpen(false);
371	  }
372	
373	  return (
374	    <Dialog open={open} onOpenChange={setOpen}>
375	      <DialogTrigger asChild>
376	        <Button size="sm" className="gap-1.5">
377	          <Plus className="h-4 w-4" />
378	          New Task
379	        </Button>
380	      </DialogTrigger>
381	      <DialogContent className="sm:max-w-md">
382	        <DialogHeader>
383	          <DialogTitle>Create task</DialogTitle>
384	        </DialogHeader>
385	        <form onSubmit={handleSubmit} className="space-y-4 pt-2">
386	          <div className="space-y-1.5">
387	            <label className="text-sm font-medium" htmlFor="task-title">
388	              Title <span className="text-destructive">*</span>
389	            </label>
390	            <Input
391	              id="task-title"
392	              placeholder="e.g. Review resumes for frontend role"
393	              value={title}
394	              onChange={(e) => setTitle(e.target.value)}
395	              required
396	              autoFocus
397	            />
398	          </div>
399	
400	          <div className="space-y-1.5">
401	            <label className="text-sm font-medium" htmlFor="task-desc">
402	              Description
403	            </label>
404	            <Textarea
405	              id="task-desc"
406	              placeholder="Optional notes or context…"
407	              value={description}
408	              onChange={(e) => setDescription(e.target.value)}
409	              rows={2}
410	              className="resize-none"
411	            />
412	          </div>
413	
414	          <div className="grid grid-cols-2 gap-3">
415	            <div className="space-y-1.5">
416	              <label className="text-sm font-medium">Assign to</label>
417	              <Select value={assignedTo} onValueChange={setAssignedTo}>
418	                <SelectTrigger>
419	                  <SelectValue placeholder="Unassigned" />
420	                </SelectTrigger>
421	                <SelectContent>
422	                  <SelectItem value="__none__">Unassigned</SelectItem>
423	                  {members.map((m) => (
424	                    <SelectItem key={m.user_id} value={m.user_id}>
425	                      {m.email ?? m.user_id.slice(0, 8) + "…"}
426	                    </SelectItem>
427	                  ))}
428	                </SelectContent>
429	              </Select>
430	            </div>
431	
432	            <div className="space-y-1.5">
433	              <label className="text-sm font-medium">Priority</label>
434	              <Select
435	                value={priority}
436	                onValueChange={(v) => setPriority(v as TaskPriority)}
437	              >
438	                <SelectTrigger>
439	                  <SelectValue />
440	                </SelectTrigger>
441	                <SelectContent>
442	                  <SelectItem value="low">Low</SelectItem>
443	                  <SelectItem value="medium">Medium</SelectItem>
444	                  <SelectItem value="high">High</SelectItem>
445	                </SelectContent>
446	              </Select>
447	            </div>
448	          </div>
449	
450	          <div className="space-y-1.5">
451	            <label className="text-sm font-medium" htmlFor="task-due">
452	              Due date
453	            </label>
454	            <Input
455	              id="task-due"
456	              type="date"
457	              value={dueDate}
458	              onChange={(e) => setDueDate(e.target.value)}
459	            />
460	          </div>
461	
462	          <div className="flex justify-end gap-2 pt-1">
463	            <Button
464	              type="button"
465	              variant="outline"
466	              onClick={() => setOpen(false)}
467	              disabled={isCreating}
468	            >
469	              Cancel
470	            </Button>
471	            <Button type="submit" disabled={isCreating || !title.trim()}>
472	              {isCreating ? (
473	                <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
474	              ) : null}
475	              Create
476	            </Button>
477	          </div>
478	        </form>
479	      </DialogContent>
480	    </Dialog>
481	  );
482	}
483	
484	// ── main page ─────────────────────────────────────────────────────────────────
485	
486	const Tasks = () => {
487	  const { user, isAdmin } = useAuth();
488	  const { team, members } = useTeam();
489	  const teamId = team?.id ?? null;
490	  const { tasks, isLoading, error, createTask, updateTask, deleteTask } =
491	    useTasks(teamId);
492	
493	  const [deletingId, setDeletingId] = useState<string | null>(null);
494	
495	  const today = new Date();
496	  const threeDaysFromNow = addDays(today, 3);
497	
498	  const overdueTasks = tasks.filter(
499	    (t) =>
500	      t.status !== "done" &&
501	      t.due_date &&
502	      isBefore(parseISO(t.due_date), today)
503	  );
504	  const dueSoonTasks = tasks.filter(
505	    (t) =>
506	      t.status !== "done" &&
507	      t.due_date &&
508	      !isBefore(parseISO(t.due_date), today) &&
509	      isBefore(parseISO(t.due_date), threeDaysFromNow)
510	  );
511	  const upcomingTasks = tasks.filter(
512	    (t) =>
513	      t.status !== "done" &&
514	      t.due_date &&
515	      !isBefore(parseISO(t.due_date), threeDaysFromNow)
516	  );
517	  const noDueDateTasks = tasks.filter(
518	    (t) => t.status !== "done" && !t.due_date
519	  );
520	  const completedTasks = tasks.filter((t) => t.status === "done");
521	
522	  async function handleToggle(task: Task) {
523	    const newStatus = task.status === "done" ? "todo" : "done";
524	    try {
525	      await updateTask.mutateAsync({ id: task.id, status: newStatus });
526	    } catch {
527	      toast.error("Failed to update task");
528	    }
529	  }
530	
531	  async function handleDelete(id: string) {
532	    setDeletingId(id);
533	    try {
534	      await deleteTask.mutateAsync(id);
535	      toast.success("Task deleted");
536	    } catch {
537	      toast.error("Failed to delete task");
538	    } finally {
539	      setDeletingId(null);
540	    }
541	  }
542	
543	  async function handleCreate(values: {
544	    title: string;
545	    description?: string;
546	    assigned_to?: string;
547	    priority: TaskPriority;
548	    due_date?: string;
549	  }) {
550	    try {
551	      await createTask.mutateAsync(values);
552	      toast.success("Task created");
553	    } catch {
554	      toast.error("Failed to create task");
555	    }
556	  }
557	
558	  const sectionProps = {
559	    members,
560	    currentUserId: user?.id ?? "",
561	    isAdmin: !!isAdmin,
562	    onToggle: handleToggle,
563	    onDelete: handleDelete,
564	    deletingId,
565	  };
566	
567	  const hasActiveTasks =
568	    overdueTasks.length +
569	      dueSoonTasks.length +
570	      upcomingTasks.length +
571	      noDueDateTasks.length >
572	    0;
573	
574	  return (
575	    <SidebarLayout>
576	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
577	        {/* Page header */}
578	        <div className="flex items-center justify-between mb-1">
579	          <div className="flex items-center gap-2">
580	            <h1 className="text-2xl font-bold text-foreground">
581	              My Tasks
582	            </h1>
583	            {overdueTasks.length > 0 && (
584	              <Badge className="bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 border-0 text-xs">
585	                {overdueTasks.length} overdue
586	              </Badge>
587	            )}
588	            {dueSoonTasks.length > 0 && (
589	              <Badge className="bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-0 text-xs">
590	                {dueSoonTasks.length} due soon
591	              </Badge>
592	            )}
593	          </div>
594	          <NewTaskDialog
595	            members={members}
596	            isCreating={createTask.isPending}
597	            onSubmit={handleCreate}
598	          />
599	        </div>
600	        <p className="text-sm text-muted-foreground mb-6">
601	          Track action items and follow-ups across your team.
602	        </p>
603	
604	        {/* Loading */}
605	        {isLoading && (
606	          <Card className="border border-border/60 shadow-sm">
607	            <CardContent className="py-3">
608	              <TasksSkeleton />
609	            </CardContent>
610	          </Card>
611	        )}
612	
613	        {/* Error state */}
614	        {!isLoading && error && (
615	          <Card className="border-destructive/50">
616	            <CardContent className="py-8 text-center">
617	              <AlertCircle className="h-8 w-8 text-destructive mx-auto mb-2" />
618	              <p className="text-sm text-muted-foreground">Failed to load data. Please refresh the page.</p>
619	            </CardContent>
620	          </Card>
621	        )}
622	
623	        {/* No team state */}
624	        {!isLoading && !teamId && (
625	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
626	            <div className="rounded-xl bg-muted/50 p-4">
627	              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
628	            </div>
629	            <div className="space-y-1">
630	              <p className="text-sm font-medium">No team yet</p>
631	              <p className="text-sm text-muted-foreground max-w-xs">
632	                Create or join a team to start managing tasks collaboratively.
633	              </p>
634	            </div>
635	          </div>
636	        )}
637	
638	        {/* Empty state */}
639	        {!isLoading && teamId && tasks.length === 0 && (
640	          <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
641	            <div className="rounded-xl bg-muted/50 p-4">
642	              <CheckSquare className="h-7 w-7 text-muted-foreground/50" />
643	            </div>
644	            <div className="space-y-1">
645	              <p className="text-sm font-medium">No tasks yet</p>
646	              <p className="text-sm text-muted-foreground max-w-xs">
647	                Create your first task to track action items and follow-ups.
648	              </p>
649	            </div>
650	            <NewTaskDialog
651	              members={members}
652	              isCreating={createTask.isPending}
653	              onSubmit={handleCreate}
654	            />
655	          </div>
656	        )}
657	
658	        {/* Task sections */}
659	        {!isLoading && teamId && (hasActiveTasks || completedTasks.length > 0) && (
660	          <div className="space-y-5">
661	            {overdueTasks.length > 0 && (
662	              <Card className="border border-border/60 shadow-sm">
663	                <CardContent className="py-3">
664	                  <TaskSection
665	                    title="Overdue"
666	                    tasks={overdueTasks}
667	                    variant="destructive"
668	                    icon={<AlertTriangle className="h-3.5 w-3.5 text-red-500 shrink-0" />}
669	                    {...sectionProps}
670	                  />
671	                </CardContent>
